/**
 * `PulseCard(SYNTHESIS)` from `scenarios[]` -- Bull then Bear, matched by `direction` rather than
 * array order, so a backend that ever emits them Bear-first still renders Bull on top per the
 * Design mockup. A scenario with an unrecognized direction is silently dropped rather than shown
 * under the wrong case label.
 */
@Composable
fun Scenarios(scenarios: List<DomainScenario>?, modifier: Modifier = Modifier) {
    val bull = scenarios.orEmpty().firstOrNull { it.direction?.uppercase() == "BULLISH" }
    val bear = scenarios.orEmpty().firstOrNull { it.direction?.uppercase() == "BEARISH" }
    if (bull == null && bear == null) return

    PulseCard(style = PulseCardStyle.SYNTHESIS, modifier = modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            SynthesisCardHeader(title = stringResource(id = R.string.stock_detail_scenarios_title))
            Spacer()

            Column(verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_medium))) {
                bull?.let {
                    ScenarioCase(
                        caseLabel = stringResource(id = R.string.stock_detail_bull_case),
                        caseColor = LocalPulseColors.current.signalBullishText,
                        casePillColor = LocalPulseColors.current.signalBullishPill,
                        scenario = it
                    )
                }
                bear?.let {
                    ScenarioCase(
                        caseLabel = stringResource(id = R.string.stock_detail_bear_case),
                        caseColor = LocalPulseColors.current.signalBearishText,
                        casePillColor = LocalPulseColors.current.signalBearishPill,
                        scenario = it
                    )
                }
            }
        }
    }
}

@Composable
private fun ScenarioCase(
    caseLabel: String,
    caseColor: androidx.compose.ui.graphics.Color,
    casePillColor: androidx.compose.ui.graphics.Color,
    scenario: DomainScenario
) {
    val pulseColors = LocalPulseColors.current

    Surface(
        color = pulseColors.surfaceTinted,
        shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_small))
    ) {
        Column(modifier = Modifier.padding(dimensionResource(id = R.dimen.padding_large))) {
            Surface(
                color = casePillColor,
                shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_pill))
            ) {
                Text(
                    text = caseLabel,
                    style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                    color = caseColor,
                    modifier = Modifier.padding(
                        horizontal = dimensionResource(id = R.dimen.padding_medium),
                        vertical = dimensionResource(id = R.dimen.padding_small)
                    )
                )
            }

            scenario.whatItWouldMean?.let {
                Spacer()
                Text(
                    text = stringResource(id = R.string.stock_detail_what_it_would_mean),
                    style = MaterialTheme.typography.labelSmall,
                    color = pulseColors.onSurfaceMuted
                )
                Text(
                    text = it,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }

            scenario.whatWouldNeedToHappen?.let {
                Spacer()
                Text(
                    text = stringResource(id = R.string.stock_detail_what_would_need_to_happen),
                    style = MaterialTheme.typography.labelSmall,
                    color = pulseColors.onSurfaceMuted
                )
                Text(
                    text = it,
                    style = MaterialTheme.typography.bodyMedium,
                    color = MaterialTheme.colorScheme.onSurface
                )
            }
        }
    }
}

@Composable
private fun Spacer() {
    androidx.compose.foundation.layout.Spacer(modifier = Modifier.height(dimensionResource(id = R.dimen.padding_medium)))
}

